-- pgvector: vector column + cosine distance operator
CREATE TABLE items (id bigint, embedding vector(1536));
SELECT id FROM items
ORDER BY embedding <=> $1   -- <=> is cosine distance
LIMIT 10;

-- update = soft delete old vector + insert new one
UPDATE items SET deleted = true WHERE id = $1;
INSERT INTO items (id, embedding) VALUES ($1, $2);
-- soft-deleted rows are cleaned up on the next index rebuild
